begin;
create extension if not exists pgtap with schema extensions;
select plan(29);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values('00000000-0000-0000-0000-000000000000','98000000-0000-4000-8000-000000000001','authenticated','authenticated','purchasing-owner@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','98000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('purchasing-test','Purchasing Test Legal','Purchasing Test','sole_proprietorship','retail','{"city":"Manila"}');
select set_config('test.purchase_org',(select id::text from public.organizations where slug='purchasing-test'),true);select set_config('test.purchase_branch',(select id::text from public.branches where organization_id=current_setting('test.purchase_org')::uuid and code='main'),true);
select is(public.can_business_permission(current_setting('test.purchase_org')::uuid,'purchasing.manage'),true,'Owner receives purchasing permissions');
select throws_ok($$select public.save_supplier(current_setting('test.purchase_org')::uuid,null,'Blocked','','','','','',30,'active','')$$,'42501','Permission denied.','Purchasing mutations require the enabled module');
select public.set_business_module_state(current_setting('test.purchase_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.purchase_org')::uuid,'inventory',true,'{}');select public.set_business_module_state(current_setting('test.purchase_org')::uuid,'expenses',true,'{}');
select set_config('test.purchase_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.purchase_org')::uuid),true);
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status) values(current_setting('test.purchase_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','98000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"98000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.set_business_module_state(current_setting('test.purchase_org')::uuid,'purchasing',true,'{}')$$,'Purchasing activates after its dependencies');
select set_config('test.supplier',public.save_supplier(current_setting('test.purchase_org')::uuid,null,'Luzon Wholesale','Ana Reyes','09171234567','orders@luzon.test','Quezon City','123-456-789',30,'active','Priority supplier')::text,true);
select results_eq($$select name,mobile,payment_terms_days,status from public.suppliers where id=current_setting('test.supplier')::uuid$$,$$select 'Luzon Wholesale'::text,'09171234567'::text,30,'active'::text$$,'Supplier details and credit terms are stored');
select set_config('test.product',public.save_catalog_product(current_setting('test.purchase_org')::uuid,null,null,'product','Rice Pack','',null,null,'pack',25,10,'exempt',0,'active',false,'[{"name":"Default","sku":"RICE-001","barcode":"4801111111111","attributes":{},"status":"active"}]','[]')::text,true);
select set_config('test.variant',(select id::text from public.product_variants where product_id=current_setting('test.product')::uuid),true);
select set_config('test.pr',public.save_purchase_request(current_setting('test.purchase_org')::uuid,current_setting('test.purchase_branch')::uuid,current_date+7,'Restock rice',('[{"productVariantId":"'||current_setting('test.variant')||'","description":"Rice Pack","quantity":10,"estimatedUnitCost":12}]')::jsonb,true,true,'manager')::text,true);
select results_eq($$select request_number,status,estimated_total from public.purchase_requests where id=current_setting('test.pr')::uuid$$,$$select 'PR-'||extract(year from current_date)::integer||'-000001','pending_approval'::text,120::numeric$$,'Submitted request enters purchase approval with calculated total');
select results_eq($$select category,status from public.approval_requests where id=(select approval_request_id from public.purchase_requests where id=current_setting('test.pr')::uuid)$$,$$select 'purchase'::text,'pending'::text$$,'Request uses the reusable Approval Engine');
select public.decide_approval(current_setting('test.purchase_org')::uuid,(select approval_request_id from public.purchase_requests where id=current_setting('test.pr')::uuid),(select step.id from public.approval_steps step join public.purchase_requests request on request.approval_request_id=step.approval_request_id where request.id=current_setting('test.pr')::uuid),'approved','Within budget');
select results_eq($$select status from public.purchase_requests where id=current_setting('test.pr')::uuid$$,$$select 'approved'::text$$,'Approval decision synchronizes the purchase request');
select set_config('test.po',public.create_purchase_order(current_setting('test.purchase_org')::uuid,current_setting('test.pr')::uuid,current_setting('test.supplier')::uuid,current_date,current_date+5,'SUP-Q-1','Deliver to main branch',0)::text,true);
select results_eq($$select order_number,status,total from public.purchase_orders where id=current_setting('test.po')::uuid$$,$$select 'PO-'||extract(year from current_date)::integer||'-000001','issued'::text,120::numeric$$,'Approved request converts into an issued purchase order');
select results_eq($$select status from public.purchase_requests where id=current_setting('test.pr')::uuid$$,$$select 'converted'::text$$,'Ordered request becomes converted');
select results_eq($$select count(*) from public.stock_movements where reference_type='goods_receipt'$$,$$select 0::bigint$$,'Issuing a purchase order does not increase inventory');
select results_eq($$select count(*) from public.stock_balances where organization_id=current_setting('test.purchase_org')::uuid$$,$$select 0::bigint$$,'Purchase order creation does not materialize a stock balance');
select is(private.can_read_purchase_order(current_setting('test.purchase_org')::uuid,current_setting('test.po')::uuid),true,'Purchase order line access helper recognizes the owner');
select results_eq($$select count(*) from public.purchase_order_lines where purchase_order_id=current_setting('test.po')::uuid$$,$$select 1::bigint$$,'Issued purchase order lines are readable');
select set_config('test.po_line',(select id::text from public.purchase_order_lines where purchase_order_id=current_setting('test.po')::uuid),true);
select set_config('test.receipt1',public.receive_purchase_order(current_setting('test.purchase_org')::uuid,current_setting('test.po')::uuid,current_setting('test.purchase_location')::uuid,now(),'DR-001','First delivery','purchase-receipt-001',('[{"purchaseOrderLineId":"'||current_setting('test.po_line')||'","quantity":4,"unitCost":12}]')::jsonb)::text,true);
select results_eq($$select status from public.purchase_orders where id=current_setting('test.po')::uuid$$,$$select 'partially_received'::text$$,'A partial delivery keeps the purchase order open');
select results_eq($$select quantity_received from public.purchase_order_lines where id=current_setting('test.po_line')::uuid$$,$$select 4::numeric$$,'Partial receipt updates cumulative received quantity');
select results_eq($$select movement_type,quantity_delta,unit_cost,reference_type,reference_id from public.stock_movements where reference_id=current_setting('test.receipt1')::uuid$$,$$select 'purchase'::text,4::numeric,12::numeric,'goods_receipt'::text,current_setting('test.receipt1')::uuid$$,'Goods receipt creates the immutable purchase movement');
select results_eq($$select quantity,average_unit_cost from public.stock_balances where organization_id=current_setting('test.purchase_org')::uuid$$,$$select 4::numeric,12::numeric$$,'Inventory increases only for physically received goods');
select results_eq($$select cost_price from public.product_variants where id=current_setting('test.variant')::uuid$$,$$select 12::numeric$$,'Latest received cost updates the product variant');
select results_eq($$select public.receive_purchase_order(current_setting('test.purchase_org')::uuid,current_setting('test.po')::uuid,current_setting('test.purchase_location')::uuid,now(),'REPLAY','','purchase-receipt-001',('[{"purchaseOrderLineId":"'||current_setting('test.po_line')||'","quantity":4,"unitCost":12}]')::jsonb)$$,$$select current_setting('test.receipt1')::uuid$$,'Receipt idempotency returns the original receipt');
select results_eq($$select count(*) from public.stock_movements where reference_type='goods_receipt'$$,$$select 1::bigint$$,'Receipt replay cannot duplicate stock');
select throws_ok($$select public.receive_purchase_order(current_setting('test.purchase_org')::uuid,current_setting('test.po')::uuid,current_setting('test.purchase_location')::uuid,now(),'OVER','','purchase-receipt-over',('[{"purchaseOrderLineId":"'||current_setting('test.po_line')||'","quantity":7,"unitCost":12}]')::jsonb)$$,'P0001','Receipt exceeds outstanding quantity.','Over-receipt is rejected');
select results_eq($$select count(*) from public.goods_receipts where idempotency_key='purchase-receipt-over'$$,$$select 0::bigint$$,'Failed receipt rolls back its receipt header');
select set_config('test.receipt2',public.receive_purchase_order(current_setting('test.purchase_org')::uuid,current_setting('test.po')::uuid,current_setting('test.purchase_location')::uuid,now(),'DR-002','Final delivery','purchase-receipt-002',('[{"purchaseOrderLineId":"'||current_setting('test.po_line')||'","quantity":6,"unitCost":14}]')::jsonb)::text,true);
select results_eq($$select status from public.purchase_orders where id=current_setting('test.po')::uuid$$,$$select 'received'::text$$,'Final receipt closes the purchase order');
select results_eq($$select quantity,average_unit_cost from public.stock_balances where organization_id=current_setting('test.purchase_org')::uuid$$,$$select 10::numeric,13.2::numeric$$,'Weighted inventory cost safely reflects partial receipts');
select results_eq($$select cost_price from public.product_variants where id=current_setting('test.variant')::uuid$$,$$select 14::numeric$$,'Most recent supplier cost remains available for future purchasing');
select set_config('test.supplier_invoice',public.save_supplier_invoice(current_setting('test.purchase_org')::uuid,current_setting('test.purchase_branch')::uuid,current_setting('test.supplier')::uuid,current_setting('test.po')::uuid,'SI-7788',current_date,current_date+30,120,14.4,'Delivered in full')::text,true);
select results_eq($$select supplier_invoice_number,status,total from public.supplier_invoices where id=current_setting('test.supplier_invoice')::uuid$$,$$select 'SI-7788'::text,'issued'::text,134.4::numeric$$,'Supplier invoice is linked to the purchasing history');
select results_eq($$select count(*) from public.goods_receipts where purchase_order_id=current_setting('test.po')::uuid$$,$$select 2::bigint$$,'Supplier history retains every partial receipt');
select results_eq($$select count(*) from public.purchasing_audit_history where organization_id=current_setting('test.purchase_org')::uuid and entity_type in('purchase_request','purchase_order','goods_receipt','supplier_invoice')$$,$$select 6::bigint$$,'Purchasing lifecycle actions generate audit history');
select throws_ok($$update public.stock_movements set quantity_delta=99 where reference_id=current_setting('test.receipt1')::uuid$$,'42501','permission denied for table stock_movements','Received stock movements remain immutable to clients');
select * from finish();rollback;
